def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

If extract_spec_version is True then will look at the type value to determine
the specification version. In the case that there is no type value or it isn't
valid, then other tests will be based on the version given in self.spec_version.
    """
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    self.inventory = inventory

    # Check that inventory is a dict
    if not isinstance(inventory, dict):
        self.error('E036a')
        return

    # Check required fields exist
    if 'id' not in inventory:
        self.error('E036b')
    if 'type' not in inventory:
        self.error('E036c')
    if 'digestAlgorithm' not in inventory:
        self.error('E036d')

    # Validate id
    if 'id' in inventory:
        self.id = inventory['id']
        if not isinstance(self.id, str):
            self.error('E037a')
        else:
            # Check if id looks like a URI (has a scheme)
            if not re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*:', self.id):
                self.warning('W005', id=self.id)

    # Validate type and extract spec version
    if 'type' in inventory:
        inv_type = inventory['type']
        if not isinstance(inv_type, str):
            self.error('E038a')
        else:
            # Check if type is a valid OCFL spec URL
            type_match = re.match(r'^https://ocfl\.io/(\d+\.\d+)/spec/#inventory$', inv_type)
            if type_match:
                type_version = type_match.group(1)
                if extract_spec_version:
                    if type_version in self.spec_versions_supported:
                        self.spec_version = type_version
                    else:
                        self.error('E038c', type=inv_type)
            else:
                if extract_spec_version:
                    self.error('E038b', type=inv_type)
                else:
                    self.error('E038a')

    # Validate digestAlgorithm
    if 'digestAlgorithm' in inventory:
        digest_alg = inventory['digestAlgorithm']
        if not isinstance(digest_alg, str):
            self.error('E039')
        else:
            try:
                digest_regex(digest_alg)
                self.digest_algorithm = digest_alg
                # Warn if not the recommended algorithm
                if digest_alg != 'sha512':
                    self.warning('W004', digest_algorithm=digest_alg)
            except ValueError:
                if not self.lax_digests:
                    self.error('E039')
                else:
                    self.digest_algorithm = digest_alg

    # Validate contentDirectory
    if 'contentDirectory' in inventory:
        content_dir = inventory['contentDirectory']
        if not isinstance(content_dir, str):
            self.error('E017')
        elif '/' in content_dir or '\\' in content_dir:
            self.error('E017')
        elif content_dir in ('', '.', '..'):
            self.error('E018')
        else:
            self.content_directory = content_dir
    else:
        self.content_directory = 'content'

    # Validate head
    if 'head' in inventory:
        self.head = inventory['head']

    # Validate manifest
    if 'manifest' in inventory:
        (manifest_files, unnormalized_digests, digests_used) = self.validate_manifest(inventory['manifest'])
        self.manifest_files = manifest_files
        self.unnormalized_digests = unnormalized_digests
    else:
        self.manifest_files = None
        self.unnormalized_digests = None
        digests_used = set()

    # Validate versions
    if 'versions' in inventory:
        versions = inventory['versions']
        if isinstance(versions, dict):
            all_versions = self.validate_versions(versions, list(versions.keys()), 
                                                   self.unnormalized_digests or set())
            self.all_versions = all_versions
        else:
            self.all_versions = []
    else:
        self.all_versions = []

    # Validate fixity if present
    if 'fixity' in inventory and self.manifest_files is not None:
        self.validate_fixity(inventory['fixity'], self.manifest_files)

    # Check digests present and used
    if self.manifest_files is not None:
        self.check_digests_present_and_used(self.manifest_files, digests_used)

