def integral(bins, edges):
    """
    Compute integral (scale for a histogram).

*bins* contain values, and *edges* form the mesh
for the integration.
Their format is defined in :class:`.histogram` description.
    """
    """
    Compute integral (scale for a histogram).

*bins* contain values, and *edges* form the mesh
for the integration.
Their format is defined in :class:`.histogram` description.
    """
    # Handle 1D case
    if not hasattr(edges[0], '__iter__'):
        # 1D: edges = [e0, e1, ...], bins = [b0, b1, ...]
        return sum(b * (edges[i+1] - edges[i]) 
                   for i, b in enumerate(bins))

    # Multidimensional case
    # Compute bin widths for each dimension
    widths = [[edge_list[i+1] - edge_list[i] 
               for i in range(len(edge_list) - 1)]
              for edge_list in edges]

    def compute_integral(bin_array, indices=()):
        if not hasattr(bin_array, '__iter__'):
            # Leaf bin - multiply by volume
            volume = 1
            for dim, idx in enumerate(indices):
                volume *= widths[dim][idx]
            return bin_array * volume
        else:
            return sum(compute_integral(sub, indices + (i,))
                       for i, sub in enumerate(bin_array))

    return compute_integral(bins)

