def identify_request(request: RequestType):
    """
    Try to identify whether this is a Diaspora request.

Try first public message. Then private message. The check if this is a legacy payload.
    """
    """
    Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Try to identify as a public MagicEnvelope payload
    try:
        body = decode_if_bytes(request.body)
        if body and body.strip().startswith("<"):
            # Try to parse as XML to see if it's a MagicEnvelope
            try:
                doc = etree.fromstring(encode_if_text(body))
                if doc.tag == "me:env" or doc.tag.endswith(":env"):
                    return True
            except (etree.XMLSyntaxError, ValueError):
                pass
    except Exception:
        pass

    # Try to identify as an encrypted payload
    try:
        body = decode_if_bytes(request.body)
        if body:
            # Check if it looks like an encrypted payload (base64 encoded JSON)
            try:
                # Try to decode as JSON first
                data = json.loads(body)
                if isinstance(data, dict) and "aes_key" in data and "encrypted_magic_envelope" in data:
                    return True
            except (json.JSONDecodeError, ValueError):
                pass

            # Try to decode as base64 and check for encrypted payload structure
            try:
                decoded = urlsafe_b64decode(body.encode() if isinstance(body, str) else body)
                data = json.loads(decoded)
                if isinstance(data, dict) and "aes_key" in data and "encrypted_magic_envelope" in data:
                    return True
            except Exception:
                pass
    except Exception:
        pass

    # Try to identify as a legacy payload (reshare or other legacy formats)
    try:
        body = decode_if_bytes(request.body)
        if body and body.strip().startswith("<"):
            try:
                doc = etree.fromstring(encode_if_text(body))
                # Check for legacy Diaspora payload tags
                if doc.tag in ("post", "reshare", "request", "comment", "like", "profile", "retraction"):
                    return True
